"""Decision trace: one JSON line per decision, so 'why did we charge / not sell?' is answerable afterwards.

The writer takes an injectable clock (replays and tests stay deterministic) and rotates by size, so the file
cannot grow without bound on a small HA host.
"""
import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Callable, Sequence

from .battery import Plan


def _utc_now() -> datetime:
    """Wall clock in UTC; the default clock of TraceWriter."""
    return datetime.now(timezone.utc)


class TraceWriter:
    """Append-only JSONL trace with size-based rotation (one rotated generation, `<name>.1`)."""

    def __init__(self, path: Path, clock: Callable[[], datetime] = _utc_now, max_bytes: int = 20_000_000, compact: bool = False,
                 generations: int = 1) -> None:
        """Remember where to write, which clock to stamp with, when to rotate and how many rotated files to keep.

        `compact` drops the spaces after separators; used for the bulky full-plan file."""
        self.path = path
        self.clock = clock
        self.max_bytes = max_bytes
        self.compact = compact
        self.generations = max(generations, 1)

    def write(self, decision: dict) -> None:
        """Append one decision, stamped with the clock; rotate first when the file is over the size limit."""
        self.path.parent.mkdir(parents=True, exist_ok=True)
        if self.path.exists() and self.path.stat().st_size >= self.max_bytes:
            self._rotate()
        line = {"ts": self.clock().isoformat(timespec="seconds"), **decision}
        separators = (",", ":") if self.compact else None
        with self.path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(line, ensure_ascii=False, separators=separators) + "\n")

    def _rotate(self) -> None:
        """Shift `<name>.N` to `<name>.N+1` (dropping the oldest) and move the live file to `<name>.1`."""
        for n in range(self.generations, 1, -1):
            older = self.path.with_name(f"{self.path.name}.{n - 1}")
            if older.exists():
                older.replace(self.path.with_name(f"{self.path.name}.{n}"))
        self.path.replace(self.path.with_name(self.path.name + ".1"))


def explain(plan: Plan, import_prices: Sequence[float], export_prices: Sequence[float]) -> dict:
    """Summarise a battery plan (prices per slot, same order as the plan) into trace fields."""
    charge = [s for s in plan.slots if s.action == "charge"]
    discharge = [s for s in plan.slots if s.action == "discharge"]

    def weighted_price(chosen, prices) -> float | None:
        """Energy-weighted average price of the chosen slots, None when there are none."""
        energy = sum(abs(s.battery_kwh) for s in chosen)
        return round(sum(abs(s.battery_kwh) * prices[s.index] for s in chosen) / energy, 4) if energy else None

    first = plan.slots[0] if plan.slots else None
    return {
        "charge_kwh": round(sum(s.battery_kwh for s in charge), 2),
        "discharge_kwh": round(-sum(s.battery_kwh for s in discharge), 2),
        "avg_charge_import_price": weighted_price(charge, import_prices),
        "avg_discharge_export_price": weighted_price(discharge, export_prices),
        "expected_saving_eur": round(plan.saving, 3),
        "first_action": first.action if first else None,
        "reason": first.reason if first else None,
        "keep_value_eur_kwh": None if first is None or first.stored_value is None else round(first.stored_value, 4),
    }
